package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"slices"
	"strings"
)

const generatedHeader = `// SPDX-License-Identifier: Apache-2.0
// SPDX-FileCopyrightText: 2026 German Federal Office for Information Security (BSI) <https://www.bsi.bund.de>
// Software-Engineering: 2026 Intevation GmbH <https://intevation.de>

// Code generated by internal/generate/bare.

`

func typedSource(packageName, body string) ([]byte, error) {
	var imports []string
	for _, pkg := range []string{"encoding/json", "errors", "fmt"} {
		qualifier := pkg
		if pkg == "encoding/json" {
			qualifier = "json"
		}
		if strings.Contains(body, qualifier+".") {
			imports = append(imports, fmt.Sprintf("%q", pkg))
		}
	}
	if len(imports) > 0 {
		imports = append(imports, "")
	}
	if strings.Contains(body, "bare.") {
		imports = append(imports, `"github.com/gocsaf/csaf/v3/internal/bare"`)
	}
	for _, pkg := range []string{"v20", "v21"} {
		if strings.Contains(body, pkg+".") {
			path := "csaf/" + pkg
			imports = append(imports, fmt.Sprintf("%q", "github.com/gocsaf/csaf/v3/"+path))
		}
	}
	source := generatedHeader + "package " + packageName + "\n\n"
	if len(imports) > 0 {
		source += "import (\n" + strings.Join(imports, "\n") + "\n)\n"
	}
	return format.Source([]byte(source + body))
}

func (m *typedModel) emitModel(packageName string) ([]byte, error) {
	var out bytes.Buffer
	for _, node := range m.structures {
		fmt.Fprintf(&out, "// %s contains common fields and optional version-specific details.\ntype %s struct {\n", node.name, node.name)
		for _, f := range node.fields {
			if f.common != nil {
				optional := f.versions[0].omitEmpty || f.versions[1].omitEmpty
				fmt.Fprintf(&out, "%s %s %s\n", f.name, typedName(f.common), jsonTag(f.jsonName, optional))
			}
		}
		for _, detail := range node.details {
			if detail != nil {
				fmt.Fprintf(&out, "*%s\n", detail.name)
			}
		}
		out.WriteString("}\n")
		for _, detail := range node.details {
			if detail == nil {
				continue
			}
			version := detail.version
			fmt.Fprintf(&out, "// %s contains fields specific to CSAF 2.%d.\ntype %s struct {\n", detail.name, version, detail.name)
			for _, f := range detail.fields {
				typ, err := wireType(f.versions[version].typ, 20+version, m.models[version])
				if err != nil {
					return nil, err
				}
				fmt.Fprintf(&out, "%s %s %s\n", f.name, typ, jsonTag(f.jsonName, f.versions[version].omitEmpty))
			}
			out.WriteString("}\n")
			for _, f := range detail.fields {
				suffix := ""
				if f.versions[1-version].typ != nil {
					suffix = fmt.Sprint(20 + version)
				}
				typ, err := wireType(f.versions[version].typ, 20+version, m.models[version])
				if err != nil {
					return nil, err
				}
				zero := wireZeroValue(f.versions[version].typ, m.models[version], typ)
				fmt.Fprintf(&out, "// Get%s%s reports whether the matching version details are present.\nfunc (v *%s) Get%s%s() (%s,bool) {\n if v == nil || v.%s == nil { return %s,false }; return v.%s.%s,true\n}\n\n", f.name, suffix, node.name, f.name, suffix, typ, detail.name, zero, detail.name, f.name)
			}
		}
	}
	return typedSource(packageName, out.String())
}

// addressExpression cancels a dereference when passing a value to a helper.
func addressExpression(value string) string {
	if pointer, ok := strings.CutPrefix(value, "*"); ok {
		return pointer
	}
	return "&" + value
}

func indexExpression(value, index string) string {
	if strings.HasPrefix(value, "*") {
		value = "(" + value + ")"
	}
	return value + "[" + index + "]"
}

func wireZeroValue(expr ast.Expr, m *model, typ string) string {
	for {
		ident, ok := expr.(*ast.Ident)
		if !ok || m.types[ident.Name] == nil {
			break
		}
		expr = m.types[ident.Name]
	}
	switch t := expr.(type) {
	case *ast.StarExpr, *ast.MapType, *ast.InterfaceType:
		return "nil"
	case *ast.ArrayType:
		if t.Len == nil {
			return "nil"
		}
	case *ast.Ident:
		value := "0"
		switch t.Name {
		case "string":
			value = `""`
		case "bool":
			value = "false"
		}
		if typ == t.Name {
			return value
		}
		return typ + "(" + value + ")"
	}
	return typ + "{}"
}

type errorPath struct {
	format  string
	indices []string
}

func fieldErrorPath(name string) errorPath {
	return errorPath{format: strings.ReplaceAll(name, "%", "%%")}
}

func (p errorPath) indexed(index string) errorPath {
	return errorPath{format: p.format + "[%d]", indices: append(slices.Clone(p.indices), index)}
}

func (p errorPath) wrap(separator string) string {
	args := append(slices.Clone(p.indices), "err")
	return fmt.Sprintf("fmt.Errorf(%q, %s)", p.format+separator+"%w", strings.Join(args, ", "))
}

func loopIndex(depth int) string {
	names := []string{"i", "j", "k"}
	if depth < len(names) {
		return names[depth]
	}
	return fmt.Sprintf("i%d", depth)
}
